//! Enabled lncrawl source catalogue.
//!
//! `lncrawl sources list -o json` is the authority on which hosts the crawler
//! can open. The snapshot in `resources/lncrawl-sources.json` is generated by
//! `scripts/build_source_catalogue.py`; a test keeps the file parseable and
//! checks that every registry search source appears in it. Search still runs
//! against the live source URL, so a stale snapshot only affects the picker,
//! never the crawler's behaviour.

use crate::sources;
use serde::{Deserialize, Serialize};
use std::sync::OnceLock;
use url::Url;

const SNAPSHOT: &str = include_str!("../resources/lncrawl-sources.json");

#[derive(Debug, Clone, Deserialize)]
struct SourceEntry {
    url: String,
    language: String,
    #[serde(default)]
    search: bool,
    #[serde(default)]
    manga: bool,
    #[serde(default)]
    mtl: bool,
}

/// One enabled source, merged with the NovelForge adapter registry.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CatalogueSource {
    pub url: String,
    pub host: String,
    /// Site language as reported by lncrawl (usually the interface/translation
    /// language), not the original work language.
    pub language: String,
    /// Original work languages this source is known to carry. Best effort:
    /// only registry-backed hosts have this evidence.
    pub origin_languages: Vec<String>,
    /// Best-effort flag for English sites that carry Korean-origin works.
    pub translated_from_korean: bool,
    /// Known catalogue or copyright caveat, when the registry has one.
    pub availability_note: Option<&'static str>,
    pub search: bool,
    pub manga: bool,
    pub mtl: bool,
    /// Registry profile id, or `None` for a direct-URL-only host.
    pub novelforge_id: Option<&'static str>,
    pub support_level: &'static str,
    pub download_ready: bool,
}

fn entries() -> &'static [SourceEntry] {
    static ENTRIES: OnceLock<Vec<SourceEntry>> = OnceLock::new();
    ENTRIES.get_or_init(|| {
        // A corrupt snapshot is a packaging error, not a reason to abort a
        // release build. Keep the app usable (with no catalogue rows) and leave
        // the reason on stderr for the diagnostics bundle.
        serde_json::from_str(SNAPSHOT).unwrap_or_else(|error| {
            eprintln!("resources/lncrawl-sources.json is invalid: {error}");
            Vec::new()
        })
    })
}

fn host_of(url: &str) -> Option<String> {
    Url::parse(url)
        .ok()
        .and_then(|parsed| parsed.host_str().map(str::to_string))
}

/// Every enabled source in the snapshot.
pub fn all() -> Vec<CatalogueSource> {
    entries()
        .iter()
        .filter_map(|entry| {
            let host = host_of(&entry.url)?;
            let profile = sources::for_host(&host);
            let origin_languages: Vec<String> = profile
                .origin_languages
                .iter()
                .map(|code| (*code).to_string())
                .collect();
            let translated_from_korean =
                entry.language == "en" && origin_languages.iter().any(|code| code == "ko");
            Some(CatalogueSource {
                url: entry.url.clone(),
                host,
                language: entry.language.clone(),
                origin_languages,
                translated_from_korean,
                availability_note: profile.availability_note,
                search: entry.search,
                manga: entry.manga,
                mtl: entry.mtl,
                novelforge_id: (profile.id != "generic").then_some(profile.id),
                support_level: profile.support.label(),
                download_ready: profile.support.is_download_ready(),
            })
        })
        .collect()
}

/// Sources that can answer a novel-title search. Manga-only entries are left
/// to the manga engine, which has a separate source list.
pub fn searchable() -> Vec<CatalogueSource> {
    all()
        .into_iter()
        .filter(|entry| entry.search && !entry.manga)
        .collect()
}

/// Resolves a picker value (full URL or bare host) to a searchable catalogue
/// entry. Returns `None` for unknown or non-searchable sources.
pub fn find_searchable(value: &str) -> Option<CatalogueSource> {
    let value = value.trim();
    if value.is_empty() {
        return None;
    }
    searchable().into_iter().find(|entry| {
        entry.url.eq_ignore_ascii_case(value)
            || entry.host.eq_ignore_ascii_case(value)
            || entry
                .url
                .trim_end_matches('/')
                .eq_ignore_ascii_case(value.trim_end_matches('/'))
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn snapshot_parses_and_is_unique() {
        let catalogue = all();
        assert!(
            catalogue.len() >= 300,
            "catalogue only has {} entries",
            catalogue.len()
        );
        let mut urls = HashSet::new();
        for entry in &catalogue {
            assert!(entry.url.starts_with("http"), "bad URL {}", entry.url);
            assert!(!entry.language.is_empty(), "missing language {}", entry.url);
            assert!(urls.insert(entry.url.clone()), "duplicate {}", entry.url);
        }
    }

    #[test]
    fn every_registry_search_source_is_searchable_in_the_catalogue() {
        for profile in sources::search_sources() {
            let host = profile.hosts.first().expect("search profile host");
            let entry = searchable()
                .into_iter()
                .find(|entry| sources::for_host(&entry.host).id == profile.id)
                .unwrap_or_else(|| panic!("{host} is missing from the catalogue"));
            assert!(entry.search, "{host} is not searchable in lncrawl");
        }
        assert!(find_searchable("wondernovels.com").is_some());
        assert!(find_searchable("https://wondernovels.com/").is_some());
        assert!(find_searchable("novelfull.net").is_none());
    }

    #[test]
    fn catalogue_marks_novelforge_support() {
        let freewebnovel = all()
            .into_iter()
            .find(|entry| entry.host == "freewebnovel.com")
            .expect("freewebnovel in catalogue");
        assert_eq!(freewebnovel.novelforge_id, Some("freewebnovel"));
        assert!(freewebnovel.download_ready);
        assert!(!freewebnovel.search);

        let unknown = all()
            .into_iter()
            .find(|entry| entry.host == "gravitytales.com")
            .expect("gravitytales in catalogue");
        assert_eq!(unknown.novelforge_id, None);
        assert!(!unknown.download_ready);
    }

    #[test]
    fn korean_origin_flags_are_best_effort_and_not_universal() {
        let novelfire = all()
            .into_iter()
            .find(|entry| entry.host == "novelfire.net")
            .expect("novelfire in catalogue");
        // NovelFire has removed Korean-origin titles for copyright reasons, so
        // it must not be advertised as a Korean-translation source.
        assert!(!novelfire.origin_languages.iter().any(|code| code == "ko"));
        assert!(!novelfire.translated_from_korean);
        assert!(novelfire.availability_note.is_some());

        let novelphoenix = all()
            .into_iter()
            .find(|entry| entry.host == "novelphoenix.net")
            .expect("novelphoenix in catalogue");
        assert!(
            novelphoenix
                .origin_languages
                .iter()
                .any(|code| code == "ko")
        );
        assert!(novelphoenix.translated_from_korean);
        assert_eq!(novelphoenix.language, "en");

        // Direct-URL-only hosts, including unknown ones, make no claim.
        let unknown = all()
            .into_iter()
            .find(|entry| entry.host == "gravitytales.com")
            .expect("gravitytales in catalogue");
        assert!(unknown.origin_languages.is_empty());
        assert!(!unknown.translated_from_korean);
        assert!(unknown.availability_note.is_none());
    }

    #[test]
    fn novelping_is_a_verified_direct_url_source() {
        let novelping = all()
            .into_iter()
            .find(|entry| entry.host == "novelping.com")
            .expect("novelping in catalogue");
        assert_eq!(novelping.novelforge_id, Some("novelping"));
        assert!(novelping.download_ready);
        assert!(!novelping.search);
        assert!(find_searchable("novelping.com").is_none());
    }
}
